"""The recall destination picker keeps ONE goal per episode.

g1190 2026-11-17 20:14-20:16: the ring was steered at タタール, then ジャンセニア,
then タタール again within five observations. ``_recall_goal`` re-derived the
nearest own castle every step and the moving cursor/hero position flipped it,
so every press looked aimless and the recall never completed.
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'src'))

from docich.hanjuku_speedrun import hanjuku_chart as chart
from docich.hanjuku_speedrun.hanjuku.flows import map as hanjuku_map


def memory(garrison, captured, hero=None):
    mem = {'chapter': 11, 'month': '63-4', 'tick': 100,
           'captured': list(captured), 'garrison': garrison, 'lost': [],
           'egg_types': {}, 'egg_uses': {}, 'house_eggs': {}}
    if hero:
        mem['general_statuses'] = {'statuses': {
            'どうし': {'general': 'どうし', 'location': hero,
                       'location_observed': True, 'tick': 90}}}
    return mem


FRONT = ['チリベット', 'マランマ', 'ゴンダル', 'ジャンセニア', 'タプロベイン']


def test_the_bound_destination_wins_over_a_changed_nearest_castle():
    mem = memory({'アルマムーン': ['どうし'], 'タタール': ['アテナ'], 'ジャンセニア': ['レモン']},
                 [*FRONT, 'タタール'], hero='ジャンセニア')
    flags = {c: 'own' for c in [*FRONT, 'タタール', 'アルマムーン']}
    recall = {'goal': 'タタール', 'destination_selected': True, 'picker_goal': 'タタール'}
    assert hanjuku_map._picker_goal(mem, flags, recall) == 'タタール'


def test_a_destination_that_is_no_longer_ours_is_measured_again():
    mem = memory({'アルマムーン': ['どうし'], 'ジャンセニア': ['レモン']},
                 ['ジャンセニア'], hero='ジャンセニア')
    flags = {'アルマムーン': 'own', 'ジャンセニア': 'own', 'タタール': 'enemy'}
    recall = {'goal': 'タタール', 'destination_selected': True, 'picker_goal': 'タタール'}
    got = hanjuku_map._picker_goal(mem, flags, recall)
    assert got != 'タタール'
    assert got in flags and flags[got] == 'own'


def test_an_unbound_picker_still_uses_the_nearest_rule():
    mem = memory({'アルマムーン': ['どうし']}, ['アルマムーン'])
    got = hanjuku_map._picker_goal(mem, None, {})
    assert got == 'アルマムーン'
